old = {"fields": [{"name": "orderId"}, {"name": "qty"}]}
new_ok = {"fields": old["fields"] + [{"name": "channel", "default": "MTS"}]}
new_bad = {"fields": old["fields"] + [{"name": "channel"}]}

def backward(reader, writer):
    have = {f["name"] for f in writer["fields"]}
    missing = [f["name"] for f in reader["fields"]
               if f["name"] not in have and "default" not in f]
    return "호환" if not missing else f"깨짐 — {missing} 에 기본값이 없다"

print(backward(new_ok, old))   # 호환
print(backward(new_bad, old))  # 깨짐 — ['channel'] 에 기본값이 없다
